args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?person ?label ?deathDateVal WHERE {
  VALUES ?person { dbr:Thomas_Valentine_Cooper dbr:John_Ellis_Roosevelt }
  OPTIONAL { ?person dbo:deathDate ?d1 . }
  OPTIONAL { ?person dbp:deathDate ?d2 . }
  BIND(coalesce(?d1, ?d2) AS ?deathDateVal)
  OPTIONAL { ?person rdfs:label ?label FILTER(lang(?label) = "en") }
}
ORDER BY ?deathDateVal

